+            overflowY: "auto",
+            overflowX: "hidden",
+            padding: 10,
+            display: "flex",
+            flexDirection: "column",
+            gap: 8,
+            boxSizing: "border-box",
+          }}
+        >
+          {children}
+        </div>
+      </div>
+    ) : null;
